<?php
// Uses only the disposable database and authenticated fixtures from integration.php.
$artWorld=$secondWorld;
$newInherited=request('admin-world-save',['title'=>'Inherited world '.$suffix,'description'=>'','enabled'=>true])['id'];
$inheritedCat=request('admin-category-save',['title'=>'Inherited category '.$suffix,'enabled'=>true,'worldIds'=>['italien']])['id'];
$fetchCategory=static fn($id)=>array_column(request('admin-data')['categories'],null,'id')[$id];
$fetchQuestion=static function($id) {
    foreach (request('admin-data')['categories'] as $category) foreach ($category['questions'] as $question) if ($question['id']===$id) return $question;
    throw new RuntimeException('Expected inherited question missing');
};
$categoryBefore=$fetchCategory($inheritedCat);
check($categoryBefore['worldIds']===['italien'],'category world selection round-trips through admin data');
$base=['categoryId'=>$inheritedCat,'question'=>'Inherited question '.$suffix,'answers'=>['A','B','C','D'],'correct'=>0,'difficulty'=>'easy','active'=>true,'worldIds'=>[],'tags'=>['Antike']];
$inheritedQ=request('admin-question-save',$base)['id'];
$extra=$base;$extra['question']='Extra direct world '.$suffix;$extra['worldIds']=[$artWorld];
$extraQ=request('admin-question-save',$extra)['id'];
$q=$fetchQuestion($inheritedQ);$qExtra=$fetchQuestion($extraQ);
check($q['directWorldIds']===[] && $q['inheritedWorldIds']===['italien'] && $q['worldIds']===['italien'],'new question inherits its category world without copied question links');
check(count($qExtra['worldIds'])===2 && $qExtra['directWorldIds']===[$artWorld],'direct extra world is combined with inherited membership without duplicate questions');
request('start-round',['categoryId'=>$inheritedCat,'worldId'=>$artWorld,'questionIds'=>[$inheritedQ]],409);
$frozen=request('start-round',['categoryId'=>$inheritedCat,'worldId'=>'italien','questionIds'=>[$inheritedQ]]);
$categoryEdit=['id'=>$inheritedCat,'title'=>$categoryBefore['title'],'enabled'=>true,'contentVersion'=>$categoryBefore['contentVersion'],'worldIds'=>[$newInherited]];
request('admin-category-save',$categoryEdit);
request('admin-category-save',$categoryEdit,409);
$updated=$fetchQuestion($inheritedQ);$updatedExtra=$fetchQuestion($extraQ);
check($updated['worldIds']===[$newInherited] && in_array($artWorld,$updatedExtra['worldIds'],true) && !in_array('italien',$updatedExtra['worldIds'],true),'changing category worlds immediately updates existing questions and retains direct extras');
request('admin-question-save',array_replace($base,['id'=>$inheritedQ,'contentVersion'=>$q['contentVersion']]),409);
check(true,'category inheritance changes invalidate stale question editors');
request('start-round',['categoryId'=>$inheritedCat,'worldId'=>'italien','questionIds'=>[$inheritedQ]],409);
$saved=request('save-result',['roundId'=>$frozen['roundId'],'answers'=>[['questionId'=>$inheritedQ,'selectedAnswers'=>[0]]]]);
$snapshot=$pdo->query('SELECT world_id,score FROM quiz_results WHERE id='.(int)$saved['resultId'])->fetch();
check($snapshot['world_id']==='italien' && (int)$snapshot['score']===2,'started round retains its original inherited world and score after category edits');
$legacyNew=$base;$legacyNew['question']='Implicit inherited question '.$suffix;unset($legacyNew['worldIds']);
$implicitId=request('admin-question-save',$legacyNew)['id'];
check($fetchQuestion($implicitId)['directWorldIds']===[] && $fetchQuestion($implicitId)['worldIds']===[$newInherited],'omitted new-question worlds use category inheritance rather than a copied Italy default');
$import=$legacyNew;$import['question']='Inherited import '.$suffix;
$importResponse=request('admin-question-import',['questions'=>[$import]]);
check($importResponse['importedCount']===1 && $importResponse['results'][0]['warnings']===[],'import inherits category defaults without legacy Italy warning');
$moveCat=request('admin-category-save',['title'=>'Move target '.$suffix,'enabled'=>true,'worldIds'=>['italien']])['id'];
request('admin-question-save',array_replace($extra,['id'=>$extraQ,'contentVersion'=>$updatedExtra['contentVersion'],'categoryId'=>$moveCat]));
$moved=$fetchQuestion($extraQ);
check($moved['inheritedWorldIds']===['italien'] && $moved['directWorldIds']===[$artWorld] && !in_array($newInherited,$moved['worldIds'],true),'moving a question recalculates inherited worlds while retaining its direct extras');
$currentCat=$fetchCategory($inheritedCat);
request('admin-category-save',['id'=>$inheritedCat,'title'=>$currentCat['title'],'enabled'=>true,'contentVersion'=>$currentCat['contentVersion'],'worldIds'=>[]]);
check($fetchQuestion($inheritedQ)['worldIds']===[] && $fetchQuestion($extraQ)['worldIds']!==[],'removing category defaults exposes unassigned questions without erasing direct extras');
request('admin-question-save',array_replace($base,['id'=>$inheritedQ,'contentVersion'=>$fetchQuestion($inheritedQ)['contentVersion']]),422);
check(true,'question without direct or inherited world cannot be explicitly saved');
// Reproduce one-time migration promotion using existing known city categories.
$pdo->exec("INSERT IGNORE INTO quiz_categories(id,title) VALUES('rom','Rom'),('florenz','Florenz')");
replace_category_worlds('rom',[]);replace_category_worlds('florenz',[$artWorld]);
$pdo->prepare('INSERT INTO quiz_questions(category_id,question,answers_json,correct_index) VALUES(?,?,?,0)')->execute(['rom','Promotion test '.$suffix,'["A","B","C","D"]']);
$promotedQ=(int)$pdo->lastInsertId();replace_question_worlds($promotedQ,['italien',$artWorld]);
$beforePromotion=$fetchQuestion($promotedQ)['worldIds'];
$resultCount=(int)$pdo->query('SELECT COUNT(*) FROM quiz_results')->fetchColumn();
$pdo->exec("DELETE FROM schema_migrations WHERE version='021_category_worlds.sql'");
execute_sql_file(__DIR__.'/../database/migrations/021_category_worlds.sql');
$pdo->exec("INSERT INTO schema_migrations(version) VALUES('021_category_worlds.sql')");
$promoted=$fetchQuestion($promotedQ);
check($promoted['worldIds']===$beforePromotion && $promoted['directWorldIds']===[$artWorld] && $promoted['inheritedWorldIds']===['italien'],'migration promotes Italian city membership without changing effective worlds or direct extras');
check(category_world_ids('florenz')===[$artWorld] && (int)$pdo->query('SELECT COUNT(*) FROM quiz_results')->fetchColumn()===$resultCount,'promotion preserves existing category settings and saved results');
replace_category_worlds('rom',[$artWorld]);replace_question_worlds($promotedQ,['italien',$artWorld]);
execute_sql_file(__DIR__.'/../database/migrations/021_category_worlds.sql');
check(category_world_ids('rom')===[$artWorld] && in_array('italien',question_world_ids($promotedQ),true),'completed migration replay does not restore removed defaults or erase later direct assignments');
